/**
 * Reproducible validation of the A3 lunar model against JPL Horizons reference data
 * (fixtures generated by reference/fetch_horizons_moon.mjs).
 */
import { dateToJD } from '../time/julian';
import { nextLunarPhase, nextLunarPhaseApprox, moonRiseSetEvents, moonPhase } from '../celestial/moon';

export interface ErrorStats {
  n: number;
  /** Signed mean (model − reference), minutes. */
  meanMin: number;
  /** Median of |error|, minutes. */
  medianAbsMin: number;
  /** 95th percentile of |error|, minutes. */
  p95AbsMin: number;
  maxAbsMin: number;
  /** Reference events with no model event within the matching window. */
  missing: number;
}

export function stats(errorsMin: number[], missing = 0): ErrorStats {
  const a = errorsMin.map(Math.abs).sort((x, y) => x - y);
  const q = (p: number) => (a.length ? a[Math.min(a.length - 1, Math.floor(p * (a.length - 1) + 0.5))] : NaN);
  return {
    n: errorsMin.length,
    meanMin: errorsMin.reduce((s, x) => s + x, 0) / Math.max(1, errorsMin.length),
    medianAbsMin: q(0.5),
    p95AbsMin: q(0.95),
    maxAbsMin: a.length ? a[a.length - 1] : NaN,
    missing,
  };
}

export interface PhaseRef { phase: 0 | 90 | 180 | 270; utc: string }

/** Model − reference timing error for each principal phase. */
export function validatePhases(ref: PhaseRef[], method: 'meeus49' | 'almanacRoot' = 'meeus49') {
  const solve = method === 'meeus49' ? nextLunarPhase : nextLunarPhaseApprox;
  const byPhase: Record<number, number[]> = { 0: [], 90: [], 180: [], 270: [] };
  const all: number[] = [];
  for (const r of ref) {
    const jdRef = dateToJD(new Date(r.utc));
    const jdModel = solve(jdRef - 2, r.phase);
    const err = (jdModel - jdRef) * 1440;
    byPhase[r.phase].push(err);
    all.push(err);
  }
  return {
    all: stats(all),
    newMoon: stats(byPhase[0]),
    firstQuarter: stats(byPhase[90]),
    fullMoon: stats(byPhase[180]),
    lastQuarter: stats(byPhase[270]),
    first: ref[0]?.utc,
    last: ref[ref.length - 1]?.utc,
  };
}

export interface RiseSetSiteRef { id: string; lat: number; lon: number; events: { type: 'rise' | 'set'; utc: string }[] }

/**
 * Match every reference rise/set with the nearest model event of the same type within ±60 min.
 * Reference times are given to the whole minute (Horizons 1-min grid), adding ≤ 0.5 min of
 * quantisation to the errors.
 */
export function validateRiseSet(sites: RiseSetSiteRef[], windowMin = 60) {
  const perSite: Record<string, ErrorStats & { lat: number }> = {};
  const all: number[] = [];
  let missingAll = 0;
  for (const s of sites) {
    const errs: number[] = [];
    let missing = 0;
    const t0 = dateToJD(new Date(s.events[0].utc)) - 1, t1 = dateToJD(new Date(s.events[s.events.length - 1].utc)) + 1;
    const model = moonRiseSetEvents(t0, t1, s.lat, s.lon);
    for (const e of s.events) {
      const jd = dateToJD(new Date(e.utc));
      let best = Infinity;
      for (const m of model) if (m.type === e.type) { const d = (m.jd - jd) * 1440; if (Math.abs(d) < Math.abs(best)) best = d; }
      if (Math.abs(best) <= windowMin) errs.push(best); else missing++;
    }
    perSite[s.id] = { ...stats(errs, missing), lat: s.lat };
    all.push(...errs);
    missingAll += missing;
  }
  return { all: stats(all, missingAll), perSite };
}

/** Illuminated fraction k: model − reference, in percentage points of the disk. */
export function validateIllumination(samples: { utc: string; illum: number }[]) {
  const err = samples.map((x) => (moonPhase(dateToJD(new Date(x.utc))).illuminated - x.illum) * 100);
  const a = err.map(Math.abs).sort((p, q) => p - q);
  return {
    n: err.length,
    meanPct: err.reduce((s, x) => s + x, 0) / err.length,
    medianAbsPct: a[Math.floor(a.length / 2)],
    p95AbsPct: a[Math.floor(0.95 * (a.length - 1))],
    maxAbsPct: a[a.length - 1],
  };
}
